#!/usr/bin/env python
"""Regenerate docs/further-reading.md from the lessons' reading.md files.

The per-lesson `## Further reading` sections are the source of truth; the doc
is an index over them so the material is browsable without the CLI. Run this
after adding or changing a lesson's links:

    uv run python tools/gen_further_reading.py
"""
from __future__ import annotations

import re

from dojo import curriculum, reading
from dojo.config import ROOT

LINK = re.compile(r"^- (\[[^\]]+\]\((https?://[^)\s]+)\).*)$", re.M)

HEADER = """# Further reading

<!-- Generated by tools/gen_further_reading.py - edit the lessons, not this file. -->

Every lesson's `reading.md` ends with a short, specific list of things worth
reading next. This page collects all of them in one place — {n} links across
{lessons} lessons — so you can browse or bookmark without going through the CLI.

To read a lesson's notes with the links in context:

```bash
uv run dojo read <lesson>          # the whole lesson's notes
uv run dojo read <lesson> <exN>    # just the theory behind one problem
```

## The four sources this course leans on

- **[The PostgreSQL manual](https://www.postgresql.org/docs/16/index.html)** —
  most links below go here. It is unusually well written; the chapters on
  [`EXPLAIN`](https://www.postgresql.org/docs/16/using-explain.html),
  [indexes](https://www.postgresql.org/docs/16/indexes.html) and
  [routine vacuuming](https://www.postgresql.org/docs/16/routine-vacuuming.html)
  are worth reading start to finish.
- **[Use The Index, Luke](https://use-the-index-luke.com/)** — Markus Winand's
  free book on indexing and SQL performance. The best single text on the
  subject, and Part 5 refers to it constantly.
- **[Modern SQL](https://modern-sql.com/)** — the same author on the parts of
  SQL that are newer than most people's mental model of it.
- **[Don't Do This](https://wiki.postgresql.org/wiki/Don%27t_Do_This)** — the
  PostgreSQL wiki's list of things that look reasonable and are not. Ten
  minutes, and it will change a schema you were about to write.

"""


def build() -> tuple[str, int]:
    lines: list[str] = []
    total = 0
    for part_name, specs in curriculum.PARTS:
        lines.append(f"## {part_name}\n")
        for spec in specs:
            doc = reading.load(spec.slug)
            section = doc.further_reading if doc else None
            if section is None:
                continue
            seen: set[str] = set()
            items = []
            for m in LINK.finditer(section.body):
                if m.group(2) in seen:
                    continue
                seen.add(m.group(2))
                items.append(m.group(1))
            if not items:
                continue
            total += len(items)
            lines.append(f"### {spec.slug}\n")
            lines.extend(f"- {i}" for i in items)
            lines.append("")
    header = HEADER.format(n=total, lessons=len(curriculum.all_lessons()))
    return header + "\n".join(lines), total


def main() -> int:
    body, total = build()
    out = ROOT / "docs" / "further-reading.md"
    out.write_text(body.rstrip() + "\n", encoding="utf-8")
    print(f"wrote {out.relative_to(ROOT)} - {total} links")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
